      "analysis": "",
      "officialAnalysis": "【句意】—皮特森叔叔明天会来我的生日派对吗？ —很遗憾他已经被派去津巴布韦当支教老师了。 【考点】现在完成时的被动语态 【解析】主语 he 和 send 之间为被动关系，要用被动语态。这件事对现在造成了不能来参加派对的影响，用现在完成时的被动语态。 其他选项：A. was sent 只是陈述过去动作，不强调对现在影响；C. had been sent 为过去完成时，语境无过去时间作参照；D. would be sent 为过去将来时，不符合当下语境。故选 B。",
